import{waterState,adhState,dialysisState,renalLedger,freshRenalLedger,renalSubstances}from './renal-models.js?v=20261023-physicscomplete01';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const rt=(x,y,s,z=16)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#f8f6f2" font-size="${z}">${esc(s)}</text>`;
const line=(d,c='#b6ced1',w=3)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
const dot=(x,y,c='#b7d6dd',r=5)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;
export const renalSVG=(a,label)=>`<svg viewBox="0 0 560 400" role="img" aria-label="${esc(label)}"><defs><radialGradient id="renalCell"><stop stop-color="#83aab9"/><stop offset="1" stop-color="#38596f"/></radialGradient></defs>${a}</svg>`;
export function renalChart({fresh=false,plotted}={}){let d=JSON.parse(JSON.stringify(fresh?freshRenalLedger:renalLedger));if(plotted)['filtered','returned','remaining'].forEach((k,i)=>d[k][2]=Math.max(0,Math.min(120,Number(plotted[i])||0)));let c=['#e9b49e','#b8d2d0','#dbc394'],a=rt(280,27,'Supplied sample amounts · common scale',19);[0,40,80,120].forEach(n=>{let y=310-n*1.75;a+=line(`M55 ${y}H535`,'#536e80',1)+rt(34,y+5,n,14);});let legend=['F: filtered','R: returned','U: urine remainder'];legend.forEach((s,i)=>a+=`<rect x="${70+i*163}" y="48" width="12" height="12" fill="${c[i]}"/>`+rt(135+i*163,59,s,13));renalSubstances.forEach((n,i)=>{let x=95+i*120;['filtered','returned','remaining'].forEach((key,j)=>{let val=d[key][i],bx=x+j*23;a+=`<rect x="${bx}" y="${310-val*1.75}" width="17" height="${Math.max(1,val*1.75)}" fill="${c[j]}"/>`+rt(bx+8,300-val*1.75,val,13);});a+=rt(x+30,340,n,16);});a+=rt(280,380,'Amounts in arbitrary units; not concentrations',14);return renalSVG(a,'Original sample amount ledger. '+renalSubstances.map((n,i)=>n+': filtered '+d.filtered[i]+', returned '+d.returned[i]+', urine remainder '+d.remaining[i]).join('; '));}
export function osmosisFigure({state='dilute',progress=0}={}){let f=waterState(state,progress),a=rt(280,32,'Water crosses a partially permeable membrane',20)+`<rect x="40" y="75" width="480" height="235" rx="35" fill="#304e64" stroke="#9cbac2"/><circle cx="280" cy="190" r="${f.radius}" fill="url(#renalCell)" stroke="#d1dcd4" stroke-width="5"/>`;
for(let i=0;i<f.inside;i++)a+=dot(258+(i%4)*15,172+Math.floor(i/4)*18);for(let i=0;i<f.outside;i++)a+=dot(80+(i%4)*24,130+Math.floor(i/4)*37);for(let i=0;i<4;i++)a+=`<rect x="${264+(i%2)*25}" y="${205+Math.floor(i/2)*14}" width="6" height="6" fill="#e1bd8e"/>`;for(let i=0;i<(state==='dilute'?2:state==='equal'?4:6);i++)a+=`<rect x="${370+(i%3)*30}" y="${155+Math.floor(i/3)*48}" width="9" height="9" fill="#e1bd8e"/>`;
let q=progress%1;a+=line('M180 175h35l-8-6m8 6-8 6')+line('M215 210h-35l8-6m-8 6 8 6')+dot(180+q*35,175)+dot(215-q*35,210)+rt(280,337,state==='dilute'?'Dilute outside: net water enters':state==='concentrated'?'Concentrated outside: net water leaves':'Similar concentrations: no net change',17)+rt(280,370,'● Water   ■ Solute · given concentrations, symbolic scale',14);return renalSVG(a,'Cell water balance: '+state+' surroundings; '+f.inside+' symbolic water units inside and '+f.outside+' outside. Bidirectional arrows indicate water motion.');}
export function filterFigure({progress=0,state=''}={}){let phase=Math.min(2,Math.floor(progress*3)),a=rt(280,27,'Filter → recover → excrete',22);let labels=['Blood','Filtered fluid','Urine remainder'];[0,1,2].forEach(i=>a+=`<rect x="${35+i*180}" y="90" width="140" height="180" rx="24" fill="${i===0?'#49677a':i===1?'#3d5c70':'#6e6665'}" stroke="#b4cace" stroke-width="2"/>`+rt(105+i*180,302,labels[i],15));a+=line('M178 140h30l-8-7m8 7-8 7')+line('M355 218h30l-8-7m8 7-8 7')+line('M210 245q-40 60-100 0','#e7c19b',3)+rt(210,337,'Useful substances return to blood',15);
for(let i=0;i<3;i++)a+=dot(65+i*35,125,'#cb9192',10);for(let i=0;i<2;i++)a+=`<polygon points="${65+i*40},180 ${75+i*40},200 ${55+i*40},200" fill="#dbc49b"/>`;
let x=phase===0?130+progress*3*110:phase===1?280-(progress*3-1)*135:320+(progress*3-2)*120;a+=dot(x,220,phase===1?'#edc58f':'#b9d6dc',7)+rt(280,65,phase===1?'Glucose example returns to blood':phase===2?'Different urea example continues towards urine':'Small substances enter filtered fluid',15)+rt(280,370,'Cells/proteins retained · schematic compartments, not nephron anatomy',12);return renalSVG(a,'Functional kidney sequence: cells and large proteins stay in blood, small substances filter, useful substances return, remainder is excreted. Stage '+(phase+1));}
export function ureaFigure({progress=0,state=''}={}){let stages=['Excess amino acids','Ammonia','Urea','Kidney removal'],n=Math.min(3,Math.floor(progress*4)),a=rt(280,28,'Liver production · kidney removal',22);stages.forEach((s,i)=>{a+=`<rect x="${20+i*138}" y="115" width="125" height="95" rx="20" fill="${i===n?'#a67e78':'#345368'}" stroke="${i===n?'#f1c798':'#99b6c0'}" stroke-width="2"/>`+rt(82+i*138,255,s,13);if(i<3)a+=line(`M${146+i*138} 160h9`);});a+=rt(215,80,'LIVER',17)+rt(492,80,'KIDNEYS',17)+rt(280,320,n===1?'Toxic intermediate: rapidly converted':n===3?'Blood transports urea for urinary excretion':'Functional stages, not a balanced chemical equation',16)+dot(58+progress*442,162,'#edd0a5',9)+rt(280,376,'Urea is a dissolved substance; urine is a mixture',15);return renalSVG(a,'Excess amino acids are processed in liver: ammonia then urea; blood transports urea to kidneys. Functional stage '+(n+1));}
export function adhFigure({state='low-water',progress=0,restored=false}={}){let f=adhState(state),a=rt(280,30,restored?'Balance restored · extra ADH drive decreases':state==='high-water'?'Less ADH · lower permeability':'More ADH · higher permeability',22)+`<rect x="45" y="95" width="195" height="205" rx="30" fill="#3c5b70" stroke="#b1c8ce"/><rect x="320" y="95" width="195" height="205" rx="30" fill="#4e6b7b" stroke="#b1c8ce"/>`+rt(140,330,'Tubule fluid',17)+rt(417,330,'Blood',17)+`<path d="M270 85V310" stroke="#e7cba9" stroke-width="5" stroke-dasharray="${state==='high-water'?'38 4':'10 10'}"/>`;let returned=Math.floor(f.recovered*progress),remaining=20-returned;for(let i=0;i<remaining;i++)a+=dot(74+(i%5)*30,130+Math.floor(i/5)*38);for(let i=0;i<returned;i++)a+=dot(352+(i%5)*30,130+Math.floor(i/5)*38);a+=line('M241 205h77l-10-8m10 8-10 8')+rt(280,366,'20 supplied water units: '+returned+' returned; '+remaining+' remain',15)+rt(280,391,'Permeability changes; ADH does not create water',13);return renalSVG(a,'Pituitary ADH affects kidney-tubule water permeability: '+f.permeability+'. '+returned+' water units returned and '+remaining+' remain in this worked sample.');}
export function dialysisFigure({progress=0,state='fresh'}={}){let matched=state==='matched',f=matched?{bloodUrea:8,fluidUrea:8}:dialysisState(progress),a=rt(280,30,'Separate channels · selective exchange',22)+`<rect x="40" y="85" width="480" height="110" rx="24" fill="#49677a"/><rect x="40" y="235" width="480" height="110" rx="24" fill="#3a596f"/>`+line('M55 214H505','#dfc89f',5)+rt(280,70,'Blood channel',17)+rt(280,374,'Dialysis fluid channel',17);for(let i=0;i<3;i++)a+=dot(95+i*85,130,'#c68d91',13);for(let i=0;i<2;i++)a+=`<polygon points="${355+i*65},113 ${369+i*65},140 ${341+i*65},140" fill="#d5be97"/>`;for(let i=0;i<f.bloodUrea;i++)a+=dot(80+i*53,172,'#c6dddd',5);for(let i=0;i<f.fluidUrea;i++)a+=dot(80+i*53,276,'#c6dddd',5);a+=line('M490 180v90l-8-10m8 10 8-10')+`<rect x="155" y="203" width="250" height="23" rx="7" fill="#203c52"/>`+rt(280,220,'Partially permeable membrane',14)+rt(280,397,matched?'Small dots: glucose · matched concentrations, no net loss':'Small dots: urea · large shapes: retained cells/proteins',12);return renalSVG(a,(matched?'Matched glucose concentrations; bidirectional movement with no net loss. ':'Dialysis: blood and fluid do not mix. ')+f.bloodUrea+' symbolic urea units in blood and '+f.fluidUrea+' in fluid; cells and proteins retained. '+(state==='matched'?'Matched useful-solute concentration prevents unnecessary net loss.':''));}
export function renalFigure(w={}){if(w.concealed)return renalSVG(rt(280,195,'Predict, then reveal the evidence',22),'Outcome concealed until prediction');if(w.kind==='ledger')return renalChart(w);if(w.kind==='osmosis')return osmosisFigure(w);if(w.kind==='filter')return filterFigure(w);if(w.kind==='urea')return ureaFigure(w);if(w.kind==='adh')return adhFigure(w);if(w.kind==='dialysis')return dialysisFigure(w);if(w.kind==='losses')return renalSVG(rt(280,45,'Trace the loss route',23)+rt(280,150,w.state==='lungs'?'Lungs → water in exhaled air':w.state==='skin'?'Skin → water, ions and urea in sweat':'Kidneys → excess water, ions and urea in urine',19)+rt(280,260,'Kidneys regulate urinary losses',20),'Loss pathways: lung water, skin sweat and controlled kidney urine losses.');return renalSVG(rt(280,40,'Compare benefits and limitations',22)+rt(280,130,'Dialysis: repeated treatment; no donor needed',18)+rt(280,195,'Transplant: donor and surgery; rejection risk',18)+rt(280,260,'Anti-rejection medicines; ongoing monitoring',18)+rt(280,345,'Suitability and individual circumstances matter',16),'Treatment comparison: dialysis needs repeated sessions; transplant needs donor/surgery with rejection and medication risks.');}
export const renalAssessmentFigure=f=>renalFigure({kind:f.diagram,fresh:!!f.fresh});
